<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/bootstrap.php';require_once __DIR__ . '/../includes/auth.php';
$user=current_user();if(!$user||!in_array($user['role'],['Administrator','Head','Clerk'],true)){http_response_code(403);exit('Access denied.');}if($_SERVER['REQUEST_METHOD']!=='POST'||!verify_csrf()){http_response_code(419);exit('This form has expired.');}
$operation=(string)($_POST['operation']??'assign');$validDate=static function(string $v):bool{$d=DateTimeImmutable::createFromFormat('!Y-m-d',$v);$e=DateTimeImmutable::getLastErrors();return preg_match('/^\d{4}-\d{2}-\d{2}$/',$v)===1&&$d!==false&&$d->format('Y-m-d')===$v&&($e===false||(!$e['warning_count']&&!$e['error_count']));};$pdo=db();
try{$pdo->beginTransaction();if($operation==='release'){$id=filter_var($_POST['allocation_id']??null,FILTER_VALIDATE_INT);$end=trim((string)($_POST['end_on']??date('Y-m-d')));if(!$id||!$validDate($end)||$end<date('Y-m-d'))throw new DomainException('Choose a valid move-out date that is today or later.');$q=$pdo->prepare("SELECT id,start_on,status FROM boarding_allocations WHERE id=:id FOR UPDATE");$q->execute(['id'=>$id]);$a=$q->fetch();if(!$a||$a['status']!=='Active')throw new DomainException('Only an active boarding allocation can be ended.');if($end<$a['start_on'])throw new DomainException('Move-out date cannot be before the allocation start date.');$q=$pdo->prepare("UPDATE boarding_allocations SET end_on=:end,status='Completed',released_by=:user WHERE id=:id AND status='Active'");$q->execute(['end'=>$end,'user'=>$user['id'],'id'=>$id]);audit_log('boarding.allocation_ended','boarding_allocations',(int)$id,['end_on'=>$end]);$pdo->commit();$_SESSION['notice']='Boarding allocation ended and retained in history.';header('Location: ../?page=boarding');exit;}
if($operation!=='assign')throw new DomainException('Choose an allocation action.');$student=filter_var($_POST['student_id']??null,FILTER_VALIDATE_INT);$room=filter_var($_POST['room_id']??null,FILTER_VALIDATE_INT);$start=trim((string)($_POST['start_on']??date('Y-m-d')));$notes=trim((string)($_POST['notes']??''));if(!$student||!$room||!$validDate($start)||$start<date('Y-m-d')||strlen($notes)>255)throw new DomainException('Choose an active learner, room, today or future start date, and a note under 256 characters.');$q=$pdo->prepare("SELECT id,sex FROM students WHERE id=:id AND status='Active' FOR UPDATE");$q->execute(['id'=>$student]);$s=$q->fetch();if(!$s)throw new DomainException('Only an active learner can be allocated.');$q=$pdo->prepare('SELECT * FROM boarding_rooms WHERE id=:id AND active=1 FOR UPDATE');$q->execute(['id'=>$room]);$r=$q->fetch();if(!$r)throw new DomainException('Choose an active room.');if(($r['gender']==='Boys'&&$s['sex']!=='M')||($r['gender']==='Girls'&&$s['sex']!=='F'))throw new DomainException('The learner’s recorded sex is not compatible with this room.');$q=$pdo->prepare("SELECT id,start_on,end_on FROM boarding_allocations WHERE student_id=:student AND status='Active' AND (end_on IS NULL OR end_on>=:start) ORDER BY start_on FOR UPDATE");$q->execute(['student'=>$student,'start'=>$start]);$active=$q->fetchAll();foreach($active as $old){if($old['start_on']>=$start)throw new DomainException('This learner already has a current or future allocation that overlaps the selected date.');$previousDay=(new DateTimeImmutable($start))->modify('-1 day')->format('Y-m-d');if($previousDay<$old['start_on'])throw new DomainException('Choose a start date after the current allocation begins to record a room move.');$q=$pdo->prepare("UPDATE boarding_allocations SET end_on=:end,status='Completed',released_by=:user WHERE id=:id AND status='Active'");$q->execute(['end'=>$previousDay,'user'=>$user['id'],'id'=>$old['id']]);} $q=$pdo->prepare("SELECT COUNT(*) FROM boarding_allocations WHERE room_id=:room AND status='Active' AND (end_on IS NULL OR end_on>=:start)");$q->execute(['room'=>$room,'start'=>$start]);if((int)$q->fetchColumn()>=(int)$r['capacity'])throw new DomainException('This room is at capacity for the requested date.');$q=$pdo->prepare('INSERT INTO boarding_allocations(student_id,room_id,start_on,notes,assigned_by) VALUES(:student,:room,:start,:notes,:user)');$q->execute(['student'=>$student,'room'=>$room,'start'=>$start,'notes'=>$notes?:null,'user'=>$user['id']]);$id=(int)$pdo->lastInsertId();audit_log('boarding.learner_allocated','boarding_allocations',$id,['student_id'=>$student,'room_id'=>$room,'start_on'=>$start]);$pdo->commit();$_SESSION['notice']='Learner boarding allocation saved.';
}catch(DomainException $e){if($pdo->inTransaction())$pdo->rollBack();$_SESSION['error']=$e->getMessage();}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();error_log('Boarding allocation failed: '.$e->getMessage());$_SESSION['error']='Could not update the boarding allocation.';}header('Location: ../?page=boarding');exit;
